<template><q-card flat bordered class="search-card" :class="{locked:bloqueada}"><q-card-section class="search-title"><q-icon name="search" color="green-8"/> Buscar productos</q-card-section><q-card-section class="q-pt-none"><q-input v-model="texto" :disable="bloqueada" outlined dense clearable autofocus label="Nombre, código o código de barras" color="green-8"><template #prepend><q-icon name="qr_code_scanner" color="green-8"/></template></q-input><div v-if="texto.trim()" class="product-options q-mt-md"><div v-for="grupo in grupos" :key="grupo.idExistencia" class="product-option"><q-avatar size="38px" color="green-1" text-color="green-9" icon="inventory_2"/><div class="product-text"><b>{{ grupo.nombreProducto }}</b><small>{{ grupo.codigoProducto }} · {{ grupo.almacen }} · {{ grupo.ubicacion }}</small><q-select v-model="seleccion[grupo.idExistencia]" :disable="bloqueada" dense outlined options-dense emit-value map-options class="presentation-select" label="Presentación" :options="grupo.presentaciones" @update:model-value="seleccionarPresentacion(grupo,$event)"/></div><div class="product-side"><strong>Bs {{ dinero(seleccionActual(grupo).precioVenta) }}</strong><small>Stock: {{ formatoCantidad(seleccionActual(grupo).stockDisponible) }}</small><q-btn :disable="bloqueada" unelevated round dense color="green-8" icon="add" @click="agregar(grupo)"/></div></div><div v-if="!grupos.length" class="empty-search">No se encontró ningún producto vendible.</div></div></q-card-section></q-card></template>
<script setup>import{computed,reactive,ref}from'vue';const props=defineProps({productos:{type:Array,default:()=>[]},bloqueada:Boolean});const emit=defineEmits(['agregar']);const texto=ref('');const seleccion=reactive({});const filtrados=computed(()=>{const q=texto.value.trim().toLowerCase();return q?props.productos.filter(p=>`${p.nombreProducto||p.nombre||''} ${p.codigoProducto||p.codigo||''} ${p.codigoBarra||''}`.toLowerCase().includes(q)):[]});const grupos=computed(()=>{const mapa=new Map();filtrados.value.forEach(item=>{const key=item.idExistencia??item.id;if(!mapa.has(key))mapa.set(key,{...item,presentaciones:[]});mapa.get(key).presentaciones.push({label:`${item.nombrePresentacion||item.presentacion||item.unidad||'Unidad'} · Bs ${dinero(item.precioVenta??item.precio)}`,value:item.idPresentacion??item.id,item})});return[...mapa.values()].map(g=>{if(seleccion[g.idExistencia]==null)seleccion[g.idExistencia]=g.presentaciones[0]?.value;return g})});function seleccionActual(g){return g.presentaciones.find(p=>p.value===seleccion[g.idExistencia])?.item||g}function seleccionarPresentacion(g,v){seleccion[g.idExistencia]=v}function agregar(g){if(props.bloqueada)return;const i=seleccionActual(g);emit('agregar',{...i,id:`${i.idExistencia}-${i.idPresentacion}`,nombre:i.nombreProducto,codigo:i.codigoProducto,precio:Number(i.precioVenta||0),stock:Number(i.stockDisponible||0),unidad:i.unidad||'UND',presentacion:i.nombrePresentacion||i.unidad})}function dinero(v){return Number(v||0).toFixed(2)}function formatoCantidad(v){return Number(v||0).toLocaleString('es-BO',{minimumFractionDigits:0,maximumFractionDigits:2})}</script>
<style scoped>.search-card{border-radius:18px;border-color:#dfeae1}.search-card.locked{opacity:.65}.search-title{color:#1b5e20;font-size:16px;font-weight:900;display:flex;gap:8px;align-items:center}.product-options{display:grid;gap:8px}.product-option{display:flex;align-items:flex-start;gap:10px;border:1px solid #e5eee6;background:#fbfdfb;border-radius:12px;padding:10px}.product-text{min-width:0;flex:1;color:#263238}.product-text b,.product-text small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.product-text small{color:#789080;font-size:11px}.presentation-select{max-width:300px;margin-top:8px}.product-side{display:flex;flex-direction:column;align-items:flex-end;gap:5px;min-width:92px}.product-side strong{color:#2e7d32}.product-side small{color:#789080;font-size:11px}.empty-search{color:#8a9990;text-align:center;padding:18px}</style>
